import { useState } from "react";
import "../App.css";

function ProfileAnalyzer() {
  const [profileText, setProfileText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const analyzeProfile = async () => {
    if (!profileText.trim()) {
      setError("Please enter your profile.");
      return;
    }

    setLoading(true);
    setError("");
    setResult(null);

    try {
      const token = localStorage.getItem("gigora_access_token");

const response = await fetch(
  "http://127.0.0.1:8000/api/profile/",
  {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      profile_text: profileText,
    }),
  }
);

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.detail || "Something went wrong."
        );
      }

      setResult(data);
      window.dispatchEvent(new Event("dashboard-update"));
    } catch (err) {
      setError(err.message);
    }

    setLoading(false);
  };

  return (
    <div className="analyzer-page">
      <div className="analyzer-card">
        <h1>AI Profile Analyzer</h1>
        <p>
          Analyze your Fiverr or Upwork profile and
          get AI-powered recommendations.
        </p>

        <textarea
          placeholder="Paste your Fiverr or Upwork profile here..."
          value={profileText}
          onChange={(e) =>
            setProfileText(e.target.value)
          }
        />

        <button
          onClick={analyzeProfile}
          disabled={loading}
        >
          {loading
            ? "Analyzing..."
            : "Analyze Profile"}
        </button>

        {error && (
          <div className="error-box">
            {error}
          </div>
        )}

        {result && (
          <div className="results">
            <div className="score-card">
              <h3>Profile Score</h3>
              <h1>{result.score}/10</h1>
            </div>

            <div className="result-card">
              <h3>Strengths</h3>
              <ul>
                {result.strengths?.map(
                  (item, index) => (
                    <li key={index}>
                      {item}
                    </li>
                  )
                )}
              </ul>
            </div>

            <div className="result-card">
              <h3>Weaknesses</h3>
              <ul>
                {result.weaknesses?.map(
                  (item, index) => (
                    <li key={index}>
                      {item}
                    </li>
                  )
                )}
              </ul>
            </div>

            <div className="result-card">
              <h3>Suggestions</h3>
              <ul>
                {result.suggestions?.map(
                  (item, index) => (
                    <li key={index}>
                      {item}
                    </li>
                  )
                )}
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default ProfileAnalyzer;
